// --- Unified endpoints ---

app.get('/api/unified/agents', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const agent of globalAgents) {
    results.push({ ...agent, scope: 'global', scopeLabel: 'Global', projectId: null, projectName: null });
  }

  for (const project of projects) {
    for (const agent of project.agents) {
      results.push({ ...agent, scope: 'project', scopeLabel: project.name, projectId: project.id, projectName: project.name });
    }
  }

  // Category filter
  const { category, tags } = req.query;
  let filtered = results;
  if (category) {
    filtered = filtered.filter(a => (a.frontmatter?.category || 'uncategorized') === category);
  }
  if (tags) {
    const tagList = tags.split(',').map(t => t.trim().toLowerCase());
    filtered = filtered.filter(a => {
      const agentTags = (a.frontmatter?.tags || '').split(',').map(t => t.trim().toLowerCase());
      return tagList.some(t => agentTags.includes(t));
    });
  }

  filtered.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(filtered);
});

